import { Component, Input, Output, EventEmitter, OnInit, OnChanges, SimpleChanges, ViewEncapsulation, OnDestroy } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { MessageFeedback } from '../../../shared/services/chatbot.service';
import { SenseSphereOAuthService } from '../../../shared/services/sensesphere-oauth.service';
import { EventManager, EventWithContent } from '../../../shared/services/broadcast.service';

type ValidLang = 'vi' | 'en';

function validateLang(value: string | null): ValidLang {
    return (value === 'vi' || value === 'en') ? value : 'vi';
}

@Component({
    selector: 'app-chatbot-message',
    templateUrl: './chatbot-message.component.html',
    styleUrls: ['chatbot-message.component.scss'],
    encapsulation: ViewEncapsulation.None
})
export class ChatbotMessageComponent implements OnInit, OnChanges, OnDestroy {
    @Input() message: string = '';
    @Input() agent: 'user' | 'bot' = 'bot';
    @Input() timestamp?: string;
    @Input() botAvatarUrl: string | null = null;
    @Input() imageUrl: string | null | undefined = null;
    @Input() promptTokens: number | undefined;
    @Input() completionTokens: number | undefined;
    @Input() totalTokens: number | undefined;
    @Input() cachedTokens: number | undefined;
    @Input() userFeedback?: MessageFeedback;

    @Output() codeClick = new EventEmitter<string>();
    @Output() copyMessage = new EventEmitter<string>();
    @Output() feedback = new EventEmitter<{ type: 'suggest' | 'rate', rating?: number }>();
    @Output() showImage = new EventEmitter<string>();

    processedContent: SafeHtml = '';
    currentLang: ValidLang = 'vi';
    private langSubscription?: Subscription;

    constructor(
        private sanitizer: DomSanitizer,
        private router: Router,
        private oauthService: SenseSphereOAuthService,
        private eventManager: EventManager
    ) {}

    getUserAvatar(): string | null {
        return this.oauthService.getUserInfo()?.avatar || null;
    }

    ngOnInit(): void {
        this.currentLang = validateLang(localStorage.getItem('lang'));

        this.langSubscription = this.eventManager.subscribe('changeLanguage', (event: EventWithContent<unknown> | string) => {
            if (typeof event === 'string') return;
            this.currentLang = validateLang((event as EventWithContent<string>).content ?? null);
        });

        this.processMessage();
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes['message'] || changes['imageUrl']) {
            this.processMessage();
        }
    }

    ngOnDestroy(): void {
        if (this.langSubscription) {
            this.eventManager.destroy(this.langSubscription);
        }
    }

    get hasTokenStats(): boolean {
        return !!this.totalTokens || !!this.promptTokens || !!this.completionTokens;
    }

    formatTime(timestamp: string): string {
        try {
            const date = new Date(timestamp);
            return date.toLocaleTimeString('vi-VN', {
                hour: '2-digit',
                minute: '2-digit'
            });
        } catch {
            return '';
        }
    }

    private processMessage(): void {
        if (!this.message) {
            this.processedContent = '';
            return;
        }

        let content = this.message;

        if (this.agent === 'bot' && this.imageUrl) {
            const escapedUrl = this.imageUrl.replace(/'/g, '&#39;');
            const imgHtml = `<img src="${escapedUrl}" class="chat-message-image" style="max-width: 300px; max-height: 200px; border-radius: 8px; margin-bottom: 8px;">`;
            content = imgHtml + content;
        }

        this.processedContent = this.sanitizer.bypassSecurityTrustHtml(this.formatMessage(content));
    }

    private formatMessage(text: string): string {
        const protectedHtml: string[] = [];
        let formatted = text.replace(/<[^>]+>/g, (match) => {
            protectedHtml.push(match);
            return `___HTML_${protectedHtml.length - 1}___`;
        });

        formatted = this.escapeHtml(formatted);

        protectedHtml.forEach((tag, index) => {
            formatted = formatted.replace(`___HTML_${index}___`, tag);
        });

        // Render markdown-style heading text from bot responses without showing raw # symbols.
        formatted = formatted.replace(/^#{1,6}\s+(.+)$/gm, '<strong>$1</strong>');

        return formatted;
    }

    onLinkClick(event: MouseEvent): void {
        const target = event.target as HTMLElement | null;
        const anchor = target?.closest('a');

        if (anchor) {
            event.preventDefault();
            const href = anchor.getAttribute('href');
            if (href) {
                this.codeClick.emit(href);
            }
        }
    }

    onCopy(): void {
        const plainText = this.message.replace(/<[^>]+>/g, '');
        this.copyMessage.emit(plainText);
    }

    onFeedback(type: 'suggest' | 'rate'): void {
        this.feedback.emit({ type });
    }

    onMessageClick(event: MouseEvent): void {
        const target = event.target as HTMLElement;
        if (target.tagName === 'IMG' && this.imageUrl) {
            event.stopPropagation();
            this.showImage.emit(this.imageUrl);
        }
    }

    private escapeHtml(text: string): string {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }
}
