import { Component, OnInit } from '@angular/core';
import { WhatNewService } from 'src/shared/services/whatnew.service';

@Component({
    selector: 'app-notification',
    templateUrl: './notification.component.html',
    styleUrls: ['./notification.component.scss'],
})
export class NotificationComponent implements OnInit {
    
    documents: any[] = [];
    selectedDocument: any = null;
    selectedItemId: number | null = null;

    constructor(private whatNewService: WhatNewService) {}

    ngOnInit(): void {
        this.getListWhatNew();
    }

    getListWhatNew() {
        this.whatNewService.getListWhatNew().subscribe((data: any) => {
            this.documents = data.data;
            if (this.documents.length > 0) {
                this.getDetailWhatNew(this.documents[0].id);
            }
        });
    }

    getDetailWhatNew(id: number) {
        this.selectedItemId = id;
        const item = this.documents.find((d: any) => d.id === id);
        if (item) {
            this.selectedDocument = {
                title: item.title,
                timestamp: item.timestamp,
                content: this.getContentForItem(item),
            };
        }
    }

    getContentForItem(item: any): string {
        const title = item.title;

        if (title.includes('Cập nhật lớn')) {
            return `Phiên bản mới mang đến <strong>nhiều cải tiến quan trọng</strong> cho hệ thống:<ul><li><strong>Y Học Cổ Truyền</strong> — bổ sung danh mục YHCT với 2 phiên bản ICD, mở rộng khả năng tra cứu</li><li><strong>ICD-10 TT06/2026/TT-BYT</strong> — hỗ trợ bộ mã lâm sàng mới theo thông tư, chatbot tự động nhận diện</li><li><strong>Chatbot i18n</strong> — tự động chuyển tiếng Việt/tiếng Anh theo ngôn ngữ bạn dùng</li><li><strong>Giao diện responsive</strong> — header tự động co giãn, banner Trợ lý AI, dễ dùng trên mọi thiết bị</li><li><strong>Sense Sphere</strong> — đổi thương hiệu Sense Hub, trải nghiệm đồng bộ hơn</li><li><strong>Server chính thức</strong> — chuyển sang production API, tốc độ nhanh và ổn định hơn hẳn</li></ul>Bạn sẽ thấy các thay đổi ngay khi đăng nhập hệ thống.`;
        }

        if (title.includes('Badge Hot/Mới và DMKT Sense')) {
            return `Sidebar đã được <strong>cập nhật với badge nổi bật và menu mới</strong>:<ul><li>Chatbot ICD-10 Sense hiển thị badge "<strong>Hot</strong>" màu đỏ với hiệu ứng pulse thu hút sự chú ý</li><li>Menu DMKT Sense mới xuất hiện — truy cập trực tiếp chatbot danh mục kỹ thuật tại dmkt.kcb.vn</li><li>Badge "Mới" màu xanh cho DMKT Sense giúp bạn không bỏ lỡ tính năng mới</li></ul>Bạn sẽ thấy các thay đổi ngay trên sidebar khi đăng nhập hệ thống.`;
        }

        if (title.includes('Cải thiện giao diện tổng thể')) {
            return `Hệ thống đã được <strong>cập nhật giao diện toàn diện</strong> với nhiều cải tiến:<ul><li>Tiêu đề header tự động thu gọn trên điện thoại, hiển thị đầy đủ trên máy tính</li><li>Banner Trợ lý AI nổi bật trên đầu trang, dễ truy cập</li><li>Nút chuyển đổi chế độ xem (cây/chi tiết) xuất hiện rõ ràng trên mobile</li></ul>Tất cả nhằm mang lại trải nghiệm dễ chịu và trực quan hơn khi sử dụng hệ thống.`;
        }

        if (title.includes('ICD-10 06/2026/TT-BYT')) {
            return `Chatbot đã được <strong>cập nhật hỗ trợ bộ mã ICD-10 mới theo Thông tư 06/2026/TT-BYT</strong>:<ul><li>Chatbot tự động nhận diện và chuyển hướng đúng bộ mã khi bạn hỏi về ICD-10, TT06 hoặc 06/2026/TT-BYT</li></ul>Bạn có thể bắt đầu trò chuyện với Chatbot để tra cứu mã lâm sàng theo thông tư mới.`;
        }

        if (title.includes('Danh mục Kỹ thuật')) {
            return `Tính năng <strong>Danh mục Kĩ thuật</strong> đã chính thức ra mắt, giúp bạn tra cứu nhanh danh mục kỹ thuật y tế:<ul><li>Truy cập trực tiếp danh mục kỹ thuật tại dmkt.kcb.vn</li></ul>Mục này xuất hiện trên sidebar, ngay sau mục <strong>SNOMED CT</strong>.`;
        }

        if (title.includes('ICF tự động chọn chương đầu tiên')) {
            return `Khi mở trang ICF (bao gồm cả chế độ song song), hệ thống sẽ <strong>tự động chọn và làm nổi bật chương đầu tiên</strong>:<ul><li>Không cần click thủ công, tiết kiệm thời gian tra cứu</li></ul>Bạn sẽ thấy chương đầu tiên được chọn tự động ngay khi vào trang.`;
        }

        if (title.includes('Sửa lỗi hiển thị trên điện thoại')) {
            return `Đã <strong>khắc phục nhiều lỗi hiển thị trên điện thoại/tablet</strong>:<ul><li>Thanh tìm kiếm không còn bị mất chữ khi thu nhỏ màn hình</li><li>Chatbot mini không bị che nội dung khi mở toàn màn hình</li></ul>Hệ thống hoạt động ổn định và dễ dùng hơn trên thiết bị di động.`;
        }

        if (title.includes("Trang thông báo")) {
            return `Chúng tôi đã phát triển <strong>trang thông báo 'Có gì mới?'</strong> với giao diện hiện đại và trực quan:<ul><li>Bố cục 2 cột: danh sách thông báo bên trái, chi tiết bên phải</li></ul>Bạn có thể truy cập tại menu <strong>"Có gì mới ?"</strong> trên sidebar để xem tất cả cập nhật.`;
        }
        
        if (title.includes('Chuông thông báo')) {
            return `Tính năng <strong>chuông thông báo</strong> đã xuất hiện trên header hệ thống:<ul><li>Nhấn vào icon chuông để xem nhanh danh sách thông báo mới nhất</li></ul>Bạn sẽ thấy icon chuông ngay cạnh thanh tìm kiếm trên cùng.`;
        }
        
        if (title.includes('Chatbot ICF')) {
            return `Chúng tôi vui mừng thông báo rằng <strong>Chatbot ICF</strong> đã chính thức ra mắt, mở rộng khả năng hỗ trợ tra cứu sang bộ mã <strong>ICF</strong>.<br><br>Bạn có thể hỏi đáp nhanh về chức năng và khuyết tật. Truy cập tại <a href="/chatbot/icf">Chatbot ICF Sense Sphere</a> để bắt đầu.`;
        }
        
        if (title.includes('nâng cấp lớn')) {
            return `Hệ thống CCMS đã được <strong>nâng cấp toàn diện</strong>:<ul><li>Nâng cấp framework Angular từ phiên bản 14 lên <strong>phiên bản 18</strong></li></ul>Những thay đổi này giúp trải nghiệm tra cứu mã lâm sàng của bạn trở nên <strong>nhanh chóng, an toàn và tiện lợi</strong> hơn bao giờ hết.`;
        }
        
        if (title.includes('Đăng nhập an toàn')) {
            return `Hệ thống đã tích hợp <strong>xác thực OAuth mới</strong> qua Sense Sphere:<ul><li>Đăng nhập an toàn hơn với xác thực đa lớp</li></ul>Thông tin của bạn được bảo mật theo tiêu chuẩn quốc tế.`;
        }
        
        if (title.includes('Giao diện được thiết kế lại')) {
            return `Hệ thống đã được <strong>thiết kế lại giao diện</strong>:<ul><li>Logo mới với biểu tượng não bộ kết hợp mạng neural và đường heartbeat</li></ul>Giao diện mới thể hiện cam kết của chúng tôi trong việc ứng dụng <strong>trí tuệ nhân tạo vào y khoa</strong>.`;
        }

        return title;
    }
}
