import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import {
    API_DASHBOARD_LINEAR,
    API_DASHBOARD_TABLE,
    API_DASHBOARD_MAP,
    API_DASHBOARD_DISEASE,
    API_DASHBOARD_HOSPITAL,
    API_DASHBOARD_TEXTBOX,
    API_DASHBOARD_SYNC,
    API_DASHBOARD_NEGA,
    API_DASHBOARD_VIETNAM,
    API_DASHBOARD_BUBBLE,
    API_DASHBOARD_MATRIX,
    API_DASHBOARD_UCOD_TEXTBOX,
    API_DASHBOARD_UCOD_BOARD,
    API_DASHBOARD_UCOD_LINE,
    API_DASHBOARD_UCOD_HEATMAP,
    API_SYS_UNIQUE_CLIENTS,
    API_SYS_UNIQUE_USAGES,
    API_SYS_TREEMAP,
} from '../api.config';

@Injectable({
  providedIn: 'root'
})
export class DashboardService {
  private line_api = API_DASHBOARD_LINEAR;
  private table_api=API_DASHBOARD_TABLE;
  private grid_api=API_DASHBOARD_MAP;
  private disease_api=API_DASHBOARD_DISEASE;
  private hospital_api=API_DASHBOARD_HOSPITAL;

  private text_api=API_DASHBOARD_TEXTBOX;
  private sync_api=API_DASHBOARD_SYNC;

  private nega_api = API_DASHBOARD_NEGA;

  private vn_api = API_DASHBOARD_VIETNAM; 
  private bubble_api = API_DASHBOARD_BUBBLE;

  private heat_api = API_DASHBOARD_MATRIX; 
  
  private ucud_text_box = API_DASHBOARD_UCOD_TEXTBOX; 

  private ucud_table = API_DASHBOARD_UCOD_BOARD; 
  private ucud_line = API_DASHBOARD_UCOD_LINE; 
  private ucud_heat= API_DASHBOARD_UCOD_HEATMAP; 
    
  private sys_line_clients_api = API_SYS_UNIQUE_CLIENTS; 
  private sys_line_usages_api = API_SYS_UNIQUE_USAGES; 
  
  private sys_sun_api = API_SYS_TREEMAP;
  
  constructor(private http: HttpClient) { }
  sysLineClients(param:string): Observable<any[]> {
    const url = `${this.sys_line_clients_api}${param}`;
    return this.http.get<any[]>(url);
  }
  sysUsagesClients(param:string): Observable<any[]> {
    const url = `${this.sys_line_usages_api}${param}`;
    return this.http.get<any[]>(url);
  }
  sysSun(param:string): Observable<any[]> {
    const url = `${this.sys_sun_api}${param}`;
    return this.http.get<any[]>(url);
  }
  heatMap(param:string): Observable<any[]> {
    const url = `${this.heat_api}${param}`;
    return this.http.get<any[]>(url);
  }
  line(param:string): Observable<any[]> {
    const url = `${this.line_api}${param}`;
    return this.http.get<any[]>(url);
  }
  nega(param:string): Observable<any[]> {
    const url = `${this.nega_api}${param}`;
    return this.http.get<any[]>(url);
  }
  ucodTable(param:string): Observable<any[]> {
    const url = `${this.ucud_table}${param}`;
    return this.http.get<any[]>(url);
  }
  ucodLine(param:string): Observable<any[]> {
    const url = `${this.ucud_line}${param}`;
    return this.http.get<any[]>(url);
  }
  ucodHeatMap(param:string): Observable<any[]> {
    const url = `${this.ucud_heat}${param}`;
    return this.http.get<any[]>(url);
  }
  ucodTextbox(param:string): Observable<any[]> {
    const url = `${this.ucud_text_box}${param}`;
    return this.http.get<any[]>(url);
  }
  textBox(param:string): Observable<any[]> {
    const url = `${this.text_api}${param}`;
    return this.http.get<any[]>(url);
  }
  sync(param:string): Observable<any[]> {
    const url = `${this.sync_api}${param}`;
    return this.http.get<any[]>(url);
  }
  table(param:string): Observable<any[]> {
    const url = `${this.table_api}${param}`;
    return this.http.get<any[]>(url);
  }
  disease(param?:string): Observable<any[]> {
    const url = `${this.disease_api}${param}`;
    return this.http.get<any[]>(url);
  }
  hospital(param?:string): Observable<any[]> {
    const url = `${this.hospital_api}${param}`;
    return this.http.get<any[]>(url);
  }
  group100(param:string): Observable<any[]> {
    const url = `${this.grid_api}${param}`;
    return this.http.get<any[]>(url);
  }
  vn(param:string): Observable<any[]> {
    const url = `${this.vn_api}${param}`;
    return this.http.get<any[]>(url);
  }
  bubble(param:string): Observable<any[]> {
    const url = `${this.bubble_api}${param}`;
    return this.http.get<any[]>(url);
  }
  
}
