import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import {
    API_ICF_ROOT,
    API_ICF_DATA,
    API_ICF_CHILD,
    API_ICF_SEARCH,
    API_ICF_TREE,
    API_FEEDBACK_BASE,
    API_DOC_LIST,
    API_DOC_DATA,
} from '../api.config';

@Injectable({
    providedIn: 'root',
})
export class IcfService {

    constructor(private httpClient: HttpClient) {
       
    }

    getChapter(lang: string): Observable<any[]> {
        return this.httpClient.get<any>(`${API_ICF_ROOT}?lang=${lang}`);
    }

    getDetailModel(model: string, id: string, lang: string) {
        const headers = new HttpHeaders({
            'X-Client-IP': localStorage.getItem('client_ip') || ''
        });
        return this.httpClient.get<any>(
            `${API_ICF_DATA}${model}?id=${id}&lang=${lang}`,
            { headers: headers }
        );
    }

    getChildrenOfModel(model: string, id: string, lang: string) {
        return this.httpClient.get<any>(`${API_ICF_CHILD}${model}?id=${id}&lang=${lang}`);
    }

    searchICF(q: any | undefined, lang: string) {
        if (!q || q === '*') {
            q = '';
        } else {
            q = q.toLowerCase();
        }
        return this.httpClient.get<any>(`${API_ICF_SEARCH}${q.trim()}?lang=${lang}&html=true`);
    }

    getListTreeOfSearch(model: string, id: string | number, lang: string) {
        return this.httpClient.get<any>(`${API_ICF_TREE}${model}?id=${id}&lang=${lang}`);
    }

    submitFeedback(feedbackData: any) {
        let csrftoken: string = '';
        if (document.cookie && document.cookie !== '') {
            const cookies = document.cookie.split(';');
            for (let i = 0; i < cookies.length; i++) {
                const cookie = cookies[i].trim();
                if (cookie.substring(0, 10) === 'csrftoken' + '=') {
                    csrftoken = decodeURIComponent(cookie.substring(10));
                    break;
                }
            }
        }
        return this.httpClient.post<any>(API_FEEDBACK_BASE, feedbackData, {
            headers: { 'X-CSRFToken': csrftoken },
        });
    }

    getListFeedback() {
        return this.httpClient.get<any>(`${API_FEEDBACK_BASE}ICF/`);
    }

    getDocumentList(category: string) {
        return this.httpClient.get<any>(API_DOC_LIST(category));
    }

    getDocumentDetails(id: number) {
        const headers = new HttpHeaders({
            'X-Client-IP': localStorage.getItem('client_ip') || ''
        });
        return this.httpClient.get(API_DOC_DATA(id), {headers: headers });
    }
}
